function createHistoricalBullet(contentId, metadata) {
  const content = historicalBulletContentById[contentId];
  if (!content) {
    throw new Error(`Unknown historical bullet content: ${contentId}`);
  }
  const bullet = {
    id: metadata.id,
    text: content.text,
    printText: content.printText,
    includeByDefault: metadata.includeByDefault
  };
  if (Object.prototype.hasOwnProperty.call(metadata, "strength")) {
    bullet.strength = metadata.strength;
  }
  bullet.targetRoles = metadata.targetRoles || [];
  if (Object.prototype.hasOwnProperty.call(metadata, "focusAreas")) {
    bullet.focusAreas = metadata.focusAreas;
  }
  bullet.skillTags = metadata.skillTags || [];
  return bullet;
}

